#pragma once

// Snaral oscillators: SubOscillator (sine/triangle) and MidOscillator (four generated band-limited families).
// JUCE-free, header-only. Algorithm version 1 (see docs/specs/oscillator-bank.md for the manifest).
//
// Band-limiting strategy: mipmapped single-cycle tables generated by inverse FFT at first use of
// WaveTables::instance() (call it from prepare(), never from render). Each family has 16 harmonic-limit
// levels (256 .. 1 harmonics); at render time the two levels that are guaranteed alias-safe for the current
// pitch are cross-faded, so pitch glide/bend never steps. Tables are immutable after construction.

#include <algorithm>
#include <array>
#include <cmath>
#include <complex>
#include <cstdint>
#include <cstring>
#include <vector>

#include "Dsp/DspUtil.h"
#include "Parameters/MacroMappings.h"
#include "Parameters/ParameterTable.h"

namespace snaral
{
enum class MidFamily : int { SawStack = 0, PulsePair = 1, FoldedTriangle = 2, FormantPair = 3 };
inline constexpr int numMidFamilies = 4;

enum class SubWave : int { Sine = 0, Triangle = 1 };

namespace osc_detail
{
inline void fft (std::vector<std::complex<double>>& a, bool inverse)
{
    const std::size_t n = a.size();
    for (std::size_t i = 1, j = 0; i < n; ++i)
    {
        std::size_t bit = n >> 1;
        for (; j & bit; bit >>= 1)
            j ^= bit;
        j ^= bit;
        if (i < j)
            std::swap (a[i], a[j]);
    }
    for (std::size_t len = 2; len <= n; len <<= 1)
    {
        const double ang = twoPi / static_cast<double> (len) * (inverse ? 1.0 : -1.0);
        const double wlr = std::cos (ang), wli = std::sin (ang);
        for (std::size_t i = 0; i < n; i += len)
        {
            double wr = 1.0, wi = 0.0;
            for (std::size_t j = 0; j < len / 2; ++j)
            {
                const auto u = a[i + j];
                const auto x = a[i + j + len / 2];
                const double vr = x.real() * wr - x.imag() * wi;
                const double vi = x.real() * wi + x.imag() * wr;
                a[i + j] = { u.real() + vr, u.imag() + vi };
                a[i + j + len / 2] = { u.real() - vr, u.imag() - vi };
                const double nwr = wr * wlr - wi * wli;
                wi = wr * wli + wi * wlr;
                wr = nwr;
            }
        }
    }
}
} // namespace osc_detail

/// Immutable mipmapped single-cycle tables. Built once (thread-safe function-local static).
class WaveTables
{
public:
    static constexpr int algorithmVersion = 1;
    static constexpr int tableSize = 2048;
    static constexpr int stride = tableSize + 3;     // 1 guard before, 2 guards after (cubic interpolation)
    static constexpr int maxHarmonics = 256;
    static constexpr int numLevels = 16;
    static constexpr int numSlices = 17;              // position slices for position-driven families
    static constexpr double rmsTarget = 0.5;          // all mid families are normalised to this RMS (peak cap 1.0)
    static constexpr double formantPeakCap = 2.0;     // Formant Pair is peaky; all other families stay <= 1 (+Gibbs)
    static constexpr double sawAmplitude = 0.8660254037844386; // rmsTarget * sqrt(3): amplitude of the base saw table
    static constexpr std::array<int, numLevels> levelHarmonics { 256, 181, 128, 90, 64, 45, 32, 22, 16, 11, 8, 5, 4, 3, 2, 1 };

    struct Family
    {
        int slices = 1;
        std::vector<float> data;
        const float* table (int slice, int level) const noexcept
        {
            return data.data() + (static_cast<std::size_t> (slice) * numLevels + static_cast<std::size_t> (level)) * stride;
        }
    };

    /// Two adjacent levels (both alias-safe) and the weight of the second one.
    struct LevelSel { int a = 0; int b = 0; float w = 0.0f; };

    static const WaveTables& instance()
    {
        static const WaveTables tables;
        return tables;
    }

    const Family& saw() const noexcept { return saw_; }
    const Family& sawStack() const noexcept { return sawStack_; }
    const Family& foldedTriangle() const noexcept { return folded_; }
    const Family& formantPair() const noexcept { return formant_; }
    const Family& triangle() const noexcept { return triangle_; }
    std::uint64_t contentHash() const noexcept { return hash_; }
    std::size_t totalFloats() const noexcept
    {
        return saw_.data.size() + sawStack_.data.size() + folded_.data.size() + formant_.data.size() + triangle_.data.size();
    }

    /// hAllowed = number of harmonics that fit below the alias limit at the current pitch.
    static LevelSel selectLevels (float hAllowed) noexcept
    {
        constexpr float topH = static_cast<float> (levelHarmonics[0]) * 1.41421356f; // virtual level above table 0
        if (! (hAllowed < topH))
            return { 0, 0, 0.0f };
        if (hAllowed >= static_cast<float> (levelHarmonics[0]))
            return { 0, 1, (topH - hAllowed) / (topH - static_cast<float> (levelHarmonics[0])) }; // weight of table 1: 0 at topH, 1 at 256
        if (! (hAllowed >= 1.0f))
            return { numLevels - 1, numLevels - 1, 0.0f };
        int j = 1;
        while (j < numLevels - 1 && static_cast<float> (levelHarmonics[static_cast<std::size_t> (j)]) > hAllowed)
            ++j;
        if (static_cast<float> (levelHarmonics[static_cast<std::size_t> (j)]) > hAllowed)
            return { numLevels - 1, numLevels - 1, 0.0f };
        if (j >= numLevels - 1)
            return { j, j, 0.0f };
        const float hi = static_cast<float> (levelHarmonics[static_cast<std::size_t> (j - 1)]);
        const float lo = static_cast<float> (levelHarmonics[static_cast<std::size_t> (j)]);
        return { j, j + 1, clampf ((hi - hAllowed) / (hi - lo), 0.0f, 1.0f) };
    }

    static float readCubic (const float* t, double phase) noexcept
    {
        const double x = phase * static_cast<double> (tableSize);
        int i = static_cast<int> (x);
        i = i < 0 ? 0 : (i > tableSize - 1 ? tableSize - 1 : i);
        const float f = static_cast<float> (x - static_cast<double> (i));
        const float* p = t + i; // p[0]=x[i-1] p[1]=x[i] p[2]=x[i+1] p[3]=x[i+2]
        const float c0 = p[1];
        const float c1 = 0.5f * (p[2] - p[0]);
        const float c2 = p[0] - 2.5f * p[1] + 2.0f * p[2] - 0.5f * p[3];
        const float c3 = 0.5f * (p[3] - p[0]) + 1.5f * (p[1] - p[2]);
        return ((c3 * f + c2) * f + c1) * f + c0;
    }

    /// Read a family at phase (0..1), position (0..1, ignored for 1-slice families) and level selection.
    static float read (const Family& fam, double phase, float position, const LevelSel& ls) noexcept
    {
        int s0 = 0;
        float sf = 0.0f;
        if (fam.slices > 1)
        {
            const float sp = clampf (position, 0.0f, 1.0f) * static_cast<float> (fam.slices - 1);
            s0 = std::min (static_cast<int> (sp), fam.slices - 2);
            sf = sp - static_cast<float> (s0);
        }
        float acc = 0.0f;
        for (int si = 0; si < 2; ++si)
        {
            const float ws = si == 0 ? 1.0f - sf : sf;
            if (ws <= 0.0f)
                continue;
            const int slice = s0 + si;
            float v = readCubic (fam.table (slice, ls.a), phase);
            if (ls.w > 0.0f)
                v += ls.w * (readCubic (fam.table (slice, ls.b), phase) - v);
            acc += ws * v;
        }
        return acc;
    }

    static constexpr int numWidths = 7;               // pulse-width grid 0.2, 0.3 ... 0.8 for correlation data

    /// Gain making the saw-difference pulse RMS 0.5 (peak <= 1 for widths 0.2..0.8 before Gibbs ripple).
    static double pulseGain (float width) noexcept
    {
        const double w = width;
        return rmsTarget / (sawAmplitude * 2.0 * std::sqrt (w * (1.0 - w)));
    }

    /// One mid family sample at phase (0..1). position drives Folded Triangle / Formant Pair, width drives Pulse Pair.
    float evalMid (MidFamily f, double phase, float position, float width, const LevelSel& ls) const noexcept
    {
        switch (f)
        {
            case MidFamily::SawStack:
                return read (sawStack_, phase, 0.0f, ls);
            case MidFamily::PulsePair:
            {
                double q = phase + 1.0 - static_cast<double> (width);
                q -= std::floor (q);
                return static_cast<float> (pulseGain (width))
                       * (read (saw_, phase, 0.0f, ls) - read (saw_, q, 0.0f, ls));
            }
            case MidFamily::FoldedTriangle:
                return read (folded_, phase, position, ls);
            case MidFamily::FormantPair:
                return read (formant_, phase, position, ls);
        }
        return 0.0f;
    }

    /// Normalised correlation between two mid families (full-band waveforms) at a position/width.
    /// Used by the Source blend to keep the crossfade level-matched (see oscillator-bank.md).
    float correlation (int a, int b, float position, float width) const noexcept
    {
        if (a == b)
            return 1.0f;
        const float pp = clampf (position, 0.0f, 1.0f) * static_cast<float> (numSlices - 1);
        const int p0 = std::min (static_cast<int> (pp), numSlices - 2);
        const float pf = pp - static_cast<float> (p0);
        const float wp = clampf ((width - 0.2f) * 10.0f, 0.0f, static_cast<float> (numWidths - 1) - 1.0e-4f);
        const int w0 = static_cast<int> (wp);
        const float wf = wp - static_cast<float> (w0);
        auto at = [&] (int pj, int wi) { return rho_[idx (a, b, pj, wi)]; };
        const float r0 = at (p0, w0) + wf * (at (p0, w0 + 1) - at (p0, w0));
        const float r1 = at (p0 + 1, w0) + wf * (at (p0 + 1, w0 + 1) - at (p0 + 1, w0));
        return r0 + pf * (r1 - r0);
    }

private:
    static constexpr std::size_t idx (int a, int b, int p, int w) noexcept
    {
        return ((static_cast<std::size_t> (a) * numMidFamilies + static_cast<std::size_t> (b)) * numSlices + static_cast<std::size_t> (p)) * numWidths
               + static_cast<std::size_t> (w);
    }

    struct Spectrum
    {
        std::array<double, maxHarmonics + 1> c {}, s {}; // x(phi) = sum c_h cos(2 pi h phi) + s_h sin(2 pi h phi)
    };

    struct Norm { double rms; double peakCap; };

    WaveTables()
    {
        // Saw (base for Pulse Pair): x = -(2/pi) sum sin(2 pi h phi)/h, scaled to amplitude sawAmplitude.
        buildFamily (saw_, 1, { rmsTarget, 1.0 }, [] (int, Spectrum& sp)
        {
            for (int h = 1; h <= maxHarmonics; ++h)
                sp.s[static_cast<std::size_t> (h)] = (2.0 / pi) / h;
        });

        // Saw Stack: three saws at fixed deterministic phase offsets (cycles), equal weights.
        buildFamily (sawStack_, 1, { rmsTarget, 1.0 }, [] (int, Spectrum& sp)
        {
            constexpr double offsets[3] = { 0.0, 0.083, 0.19 };
            for (int h = 1; h <= maxHarmonics; ++h)
            {
                double zr = 0.0, zi = 0.0;
                for (const double o : offsets)
                {
                    zr += std::cos (twoPi * h * o);
                    zi += std::sin (twoPi * h * o);
                }
                zr /= 3.0;
                zi /= 3.0;
                const double a = (2.0 / pi) / h;
                sp.c[static_cast<std::size_t> (h)] = a * zi;
                sp.s[static_cast<std::size_t> (h)] = a * zr;
            }
        });

        // Folded Triangle: fold(g * tri), g = 1 + 3 p^2, fold = triangle wrap (2/pi) asin(sin(pi u / 2)).
        buildFamily (folded_, numSlices, { rmsTarget, 1.0 }, [] (int slice, Spectrum& sp)
        {
            const double p = static_cast<double> (slice) / (numSlices - 1);
            const double g = 1.0 + 3.0 * p * p;
            constexpr int m = 8192;
            std::vector<std::complex<double>> z (static_cast<std::size_t> (m));
            for (int n = 0; n < m; ++n)
            {
                const double ph = static_cast<double> (n) / m;
                double q = ph + 0.25;
                q -= std::floor (q);
                const double tri = 1.0 - 4.0 * std::abs (q - 0.5);
                z[static_cast<std::size_t> (n)] = (2.0 / pi) * std::asin (std::sin (0.5 * pi * g * tri));
            }
            osc_detail::fft (z, false);
            for (int h = 1; h <= maxHarmonics; ++h)
            {
                sp.c[static_cast<std::size_t> (h)] = 2.0 * z[static_cast<std::size_t> (h)].real() / m;
                sp.s[static_cast<std::size_t> (h)] = -2.0 * z[static_cast<std::size_t> (h)].imag() / m;
            }
        });

        // Formant Pair: two 1/h harmonic sources, each with a log-Gaussian peak in harmonic-number space.
        // Source 1 peak at 2*4^p, source 2 (0.7 weight, 1/8 cycle phase shift) peak at 5*6^p; p = position.
        buildFamily (formant_, numSlices, { rmsTarget, formantPeakCap }, [] (int slice, Spectrum& sp)
        {
            const double p = static_cast<double> (slice) / (numSlices - 1);
            const double l1 = std::log (2.0 * std::pow (4.0, p));
            const double l2 = std::log (5.0 * std::pow (6.0, p));
            constexpr double sigma = 0.30;
            for (int h = 1; h <= maxHarmonics; ++h)
            {
                const double lh = std::log (static_cast<double> (h));
                const double b1 = std::exp (-0.5 * ((lh - l1) / sigma) * ((lh - l1) / sigma));
                const double b2 = std::exp (-0.5 * ((lh - l2) / sigma) * ((lh - l2) / sigma));
                const double a1 = (0.10 + b1) / h;
                const double a2 = 0.7 * (0.10 + b2) / h;
                const double d = 0.25 * pi * h; // 2 pi h * 0.125
                sp.s[static_cast<std::size_t> (h)] = a1 + a2 * std::cos (d);
                sp.c[static_cast<std::size_t> (h)] = a2 * std::sin (d);
            }
        });

        // Triangle (sub): odd harmonics, (8/pi^2) (-1)^((h-1)/2) sin(2 pi h phi) / h^2, peak normalised to 1.
        buildFamily (triangle_, 1, { 1.0e9, 1.0 }, [] (int, Spectrum& sp)
        {
            for (int h = 1; h <= maxHarmonics; h += 2)
                sp.s[static_cast<std::size_t> (h)] = (8.0 / (pi * pi)) * (((h - 1) / 2) % 2 == 0 ? 1.0 : -1.0) / (static_cast<double> (h) * h);
        });

        buildCorrelations();

        std::uint64_t hsh = 1469598103934665603ull;
        for (const Family* f : { &saw_, &sawStack_, &folded_, &formant_, &triangle_ })
            for (const float v : f->data)
            {
                std::uint32_t bits;
                std::memcpy (&bits, &v, sizeof bits);
                for (int b = 0; b < 4; ++b)
                {
                    hsh ^= (bits >> (8 * b)) & 0xffu;
                    hsh *= 1099511628211ull;
                }
            }
        hash_ = hsh;
    }

    void buildCorrelations()
    {
        rho_.assign (static_cast<std::size_t> (numMidFamilies) * numMidFamilies * numSlices * numWidths, 1.0f);
        const LevelSel full { 0, 0, 0.0f };
        for (int a = 0; a < numMidFamilies; ++a)
            for (int b = a + 1; b < numMidFamilies; ++b)
                for (int p = 0; p < numSlices; ++p)
                    for (int w = 0; w < numWidths; ++w)
                    {
                        const float pos = static_cast<float> (p) / (numSlices - 1);
                        const float width = 0.2f + 0.1f * static_cast<float> (w);
                        double ab = 0.0, aa = 0.0, bb = 0.0;
                        for (int n = 0; n < tableSize; ++n)
                        {
                            const double ph = static_cast<double> (n) / tableSize;
                            const double va = evalMid (static_cast<MidFamily> (a), ph, pos, width, full);
                            const double vb = evalMid (static_cast<MidFamily> (b), ph, pos, width, full);
                            ab += va * vb; aa += va * va; bb += vb * vb;
                        }
                        const float r = static_cast<float> (ab / std::sqrt (std::max (aa * bb, 1.0e-30)));
                        rho_[idx (a, b, p, w)] = r;
                        rho_[idx (b, a, p, w)] = r;
                    }
    }

    template <typename SpectrumFn>
    static void buildFamily (Family& fam, int slices, Norm norm, SpectrumFn&& fn)
    {
        fam.slices = slices;
        fam.data.assign (static_cast<std::size_t> (slices) * numLevels * stride, 0.0f);
        std::vector<std::complex<double>> z (static_cast<std::size_t> (tableSize));
        std::array<double, tableSize> tmp {};
        for (int slice = 0; slice < slices; ++slice)
        {
            Spectrum sp;
            fn (slice, sp);

            double energy = 0.0;
            for (int h = 1; h <= maxHarmonics; ++h)
                energy += 0.5 * (sp.c[static_cast<std::size_t> (h)] * sp.c[static_cast<std::size_t> (h)]
                                 + sp.s[static_cast<std::size_t> (h)] * sp.s[static_cast<std::size_t> (h)]);
            const double rms = std::sqrt (std::max (energy, 1.0e-30));

            double scale = 1.0;
            for (int pass = 0; pass < 2; ++pass)
            {
                for (int level = 0; level < numLevels; ++level)
                {
                    const int hMax = levelHarmonics[static_cast<std::size_t> (level)];
                    std::fill (z.begin(), z.end(), std::complex<double> { 0.0, 0.0 });
                    for (int h = 1; h <= hMax; ++h)
                    {
                        const std::complex<double> v { 0.5 * sp.c[static_cast<std::size_t> (h)], -0.5 * sp.s[static_cast<std::size_t> (h)] };
                        z[static_cast<std::size_t> (h)] = v;
                        z[static_cast<std::size_t> (tableSize - h)] = std::conj (v);
                    }
                    osc_detail::fft (z, true);
                    for (int n = 0; n < tableSize; ++n)
                        tmp[static_cast<std::size_t> (n)] = z[static_cast<std::size_t> (n)].real() * scale;

                    if (pass == 0)
                    {
                        if (level == 0)
                        {
                            double peak = 0.0;
                            for (const double v : tmp)
                                peak = std::max (peak, std::abs (v));
                            scale = std::min (norm.rms / rms, norm.peakCap / std::max (peak, 1.0e-12));
                        }
                        break; // pass 0 only measures level 0
                    }
                    float* dst = fam.data.data() + (static_cast<std::size_t> (slice) * numLevels + static_cast<std::size_t> (level)) * stride;
                    dst[0] = static_cast<float> (tmp[tableSize - 1]);
                    for (int n = 0; n < tableSize; ++n)
                        dst[n + 1] = static_cast<float> (tmp[static_cast<std::size_t> (n)]);
                    dst[tableSize + 1] = static_cast<float> (tmp[0]);
                    dst[tableSize + 2] = static_cast<float> (tmp[1]);
                }
            }
        }
    }

    Family saw_, sawStack_, folded_, formant_, triangle_;
    std::vector<float> rho_;
    std::uint64_t hash_ = 0;
};

// ---------------------------------------------------------------------------------------------------------

/// Fraction of Nyquist usable by harmonics (guard against interpolation images).
inline constexpr float oscNyquistGuard = 0.95f;

inline float oscHarmonicsAllowed (float hz, double sampleRate) noexcept
{
    return hz > 0.0f ? static_cast<float> (0.5 * oscNyquistGuard * sampleRate) / hz : 1.0e9f;
}

struct SubOscParams
{
    SubWave wave = SubWave::Sine;
    float tuneRatio = 1.0f; // sub_tune_cents as a frequency ratio

    static SubOscParams from (const ParamSnapshot& s) noexcept
    {
        SubOscParams p;
        p.wave = s.choice (P::sub_waveform) == 1 ? SubWave::Triangle : SubWave::Sine;
        p.tuneRatio = std::exp2 (clampf (s[P::sub_tune_cents], -50.0f, 50.0f) / 1200.0f);
        return p;
    }
};

/// Sine / triangle sub oscillator. Phase is a double accumulator; reset(phase) is the deterministic start.
class SubOscillator
{
public:
    void prepare (double sampleRate)
    {
        sr_ = std::isfinite (sampleRate) && sampleRate > 1000.0 ? sampleRate : 44100.0;
        tables_ = &WaveTables::instance();
        sineW_.prepare (sr_, 5.0f);
        triW_.prepare (sr_, 5.0f);
        reset (0.0);
    }

    /// Deterministic phase reset (0 = rising zero crossing). Weights snap to the current waveform.
    void reset (double startPhase = 0.0) noexcept
    {
        phase_ = startPhase - std::floor (startPhase);
        sineW_.reset (wave_ == SubWave::Sine ? 1.0f : 0.0f);
        triW_.reset (wave_ == SubWave::Triangle ? 1.0f : 0.0f);
        sineW_.setTarget (sineW_.current());
        triW_.setTarget (triW_.current());
    }

    void setWaveform (SubWave w) noexcept
    {
        wave_ = w;
        sineW_.setTarget (w == SubWave::Sine ? 1.0f : 0.0f);
        triW_.setTarget (w == SubWave::Triangle ? 1.0f : 0.0f);
    }

    double phase() const noexcept { return phase_; }

    float process (float hz) noexcept
    {
        hz = std::isfinite (hz) && hz > 0.0f ? std::min (hz, static_cast<float> (0.49 * sr_)) : 0.0f;
        const float ws = sineW_.next();
        const float wt = triW_.next();
        float out = 0.0f;
        if (ws > 0.0f)
            out += ws * static_cast<float> (std::sin (twoPi * phase_));
        if (wt > 0.0f)
            out += wt * WaveTables::read (tables_->triangle(), phase_, 0.0f, WaveTables::selectLevels (oscHarmonicsAllowed (hz, sr_)));
        phase_ += static_cast<double> (hz) / sr_;
        phase_ -= std::floor (phase_);
        return out;
    }

private:
    double sr_ = 44100.0, phase_ = 0.0;
    const WaveTables* tables_ = nullptr;
    SubWave wave_ = SubWave::Sine;
    Smoother sineW_, triW_;
};

// ---------------------------------------------------------------------------------------------------------

struct MidOscParams
{
    int sourceA = 0, sourceB = 1;
    float blend = 0.0f;       // 0..1 after Growl bias, clamped
    float position = 0.5f;    // 0..1 baseline
    float pulseWidth = 0.5f;  // 0.2..0.8
    float tuneRatio = 1.0f;   // mid_tune_cents as a frequency ratio

    static MidOscParams from (const ParamSnapshot& s) noexcept
    {
        MidOscParams p;
        p.sourceA = std::clamp (s.choice (P::mid_source_a), 0, numMidFamilies - 1);
        p.sourceB = std::clamp (s.choice (P::mid_source_b), 0, numMidFamilies - 1);
        p.blend = growlSourceBlend (s.percent (P::mid_blend), s.percent (P::growl));
        p.position = clampf (s.percent (P::mid_table_position), 0.0f, 1.0f);
        p.pulseWidth = clampf (s.percent (P::mid_pulse_width), 0.2f, 0.8f);
        p.tuneRatio = std::exp2 (clampf (s[P::mid_tune_cents], -50.0f, 50.0f) / 1200.0f);
        return p;
    }
};

/// Mid oscillator: Source A/B equal-power crossfade of the generated families. Per-sample pitch (Hz) and
/// per-sample position. One shared phase for both sources (phase-locked, deterministic).
class MidOscillator
{
public:
    void prepare (double sampleRate)
    {
        sr_ = std::isfinite (sampleRate) && sampleRate > 1000.0 ? sampleRate : 44100.0;
        tables_ = &WaveTables::instance(); // builds tables on first use: keep out of the render path
        for (auto& w : weight_)
            w.prepare (sr_, 5.0f);
        pos_.prepare (sr_, 5.0f);
        width_.prepare (sr_, 5.0f);
        setParams (MidOscParams {});
        reset (0.0);
    }

    void setParams (const MidOscParams& p) noexcept
    {
        params_ = p;
        const float blend = clampf (p.blend, 0.0f, 1.0f);
        float target[numMidFamilies] = {};
        const int a = std::clamp (p.sourceA, 0, numMidFamilies - 1);
        const int b = std::clamp (p.sourceB, 0, numMidFamilies - 1);
        if (a == b)
            target[a] = 1.0f; // identical sources: no crossfade (a correlated equal-power fade would bump +3 dB)
        else
        {
            target[a] = blend >= 1.0f ? 0.0f : static_cast<float> (std::cos (0.5 * pi * blend));
            target[b] = blend <= 0.0f ? 0.0f : static_cast<float> (std::sin (0.5 * pi * blend));
        }
        for (int i = 0; i < numMidFamilies; ++i)
            weight_[static_cast<std::size_t> (i)].setTarget (target[i]);
        pos_.setTarget (clampf (p.position, 0.0f, 1.0f));
        width_.setTarget (clampf (p.pulseWidth, 0.2f, 0.8f));
    }

    /// Deterministic reset: phase and all smoothers snap to the current targets.
    void reset (double startPhase = 0.0) noexcept
    {
        phase_ = startPhase - std::floor (startPhase);
        for (auto& w : weight_)
            w.reset (w.target());
        pos_.reset (pos_.target());
        width_.reset (width_.target());
        lastHz_ = -1.0f;
    }

    double phase() const noexcept { return phase_; }

    /// hz: oscillator fundamental (voice pitch incl. glide/bend/tune). position: 0..1 (already modulated).
    float process (float hz, float position) noexcept
    {
        hz = std::isfinite (hz) && hz > 0.0f ? std::min (hz, static_cast<float> (0.49 * sr_)) : 0.0f;
        if (hz != lastHz_)
        {
            lastHz_ = hz;
            levels_ = WaveTables::selectLevels (oscHarmonicsAllowed (hz, sr_));
        }
        pos_.setTarget (clampf (sanitize (position), 0.0f, 1.0f));
        const float pos = pos_.next();
        const float width = width_.next();

        float xs[numMidFamilies], ws[numMidFamilies];
        int ids[numMidFamilies];
        int n = 0;
        for (int f = 0; f < numMidFamilies; ++f)
        {
            const float w = weight_[static_cast<std::size_t> (f)].next();
            if (w <= 0.0f)
                continue;
            ids[n] = f;
            ws[n] = w;
            xs[n] = tables_->evalMid (static_cast<MidFamily> (f), phase_, pos, width, levels_);
            ++n;
        }
        float sum = 0.0f, sw2 = 0.0f;
        for (int i = 0; i < n; ++i)
        {
            sum += ws[i] * xs[i];
            sw2 += ws[i] * ws[i];
        }
        float kappa = 1.0f;
        if (n > 1)
        {
            float pw = sw2;
            for (int i = 0; i < n; ++i)
                for (int j = i + 1; j < n; ++j)
                    pw += 2.0f * ws[i] * ws[j] * tables_->correlation (ids[i], ids[j], pos, width);
            kappa = std::min (std::sqrt (sw2 / std::max (pw, 1.0e-6f)), 2.0f);
        }
        const float out = kappa * sum;
        phase_ += static_cast<double> (hz) / sr_;
        phase_ -= std::floor (phase_);
        return out;
    }

    /// Output using the baseline position of setParams().
    float process (float hz) noexcept { return process (hz, params_.position); }

private:
    double sr_ = 44100.0, phase_ = 0.0;
    const WaveTables* tables_ = nullptr;
    MidOscParams params_;
    std::array<Smoother, numMidFamilies> weight_;
    Smoother pos_, width_;
    float lastHz_ = -1.0f;
    WaveTables::LevelSel levels_;
};
} // namespace snaral
